excels.excel:

EXPORT WITH SHEET="售后服务工单台账", HEADER=true,
    MAPPING={"a":"服务工程师","b":"工单号","c":"客户","d":"服务时长(h)","e":"上门费单价","f":"服务费","g":"满意度"},
    FORMAT={"d":"#,##0.0","e":"#,##0.00","f":"#,##0.00","g":"0"},
    FORMULAS={
        F2:'D2*E2',F3:'D3*E3',F4:'SUM(F2:F3)',
        F5:'D5*E5',F6:'D6*E6',F7:'D7*E7',F8:'SUM(F5:F7)',
        F9:'F4+F8'
    },
    STYLE={
        ROW 4:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        ROW 8:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        ROW 9:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center}
    },
    MERGE:{
        RANGE A2:A3 WITH MERGE_WITH_FIRST,
        RANGE A5:A7 WITH MERGE_WITH_FIRST
    }
